package mkrlwe

// Tests of the exact discrete Gaussian flooding sampler (CKS20).
//
// Exactness is argued by the algorithm (flooding_exact.go header) and checked
// here by a DIFFERENTIAL test against the authors' reference implementation:
// both are driven by the same deterministic word stream and must agree sample
// by sample (testdata/cks20_reference_vectors.txt, generated by
// gen_ref_vectors.py from a diff-checked transcription of discretegauss.py).
// The statistical tests below are regression checks only; they do not
// establish exactness.

import (
	"bufio"
	"crypto/sha256"
	"encoding/binary"
	"fmt"
	"math"
	"math/big"
	"os"
	"runtime"
	"strings"
	"testing"
	"time"

	"github.com/ldsec/lattigo/v2/ring"
	"github.com/ldsec/lattigo/v2/rlwe"
	"github.com/ldsec/lattigo/v2/utils"
)

// shaWords is the deterministic test stream SHA-256(seed || ctr_le64) -> 4 LE words.
type shaWords struct {
	seed  []byte
	ctr   uint64
	buf   []uint64
	words uint64
}

func (s *shaWords) uint64() uint64 {
	if len(s.buf) == 0 {
		in := make([]byte, len(s.seed)+8)
		copy(in, s.seed)
		binary.LittleEndian.PutUint64(in[len(s.seed):], s.ctr)
		h := sha256.Sum256(in)
		for i := 0; i < 4; i++ {
			s.buf = append(s.buf, binary.LittleEndian.Uint64(h[8*i:]))
		}
		s.ctr++
	}
	s.words++
	w := s.buf[0]
	s.buf = s.buf[1:]
	return w
}

func mustRat(t testing.TB, s string) *big.Rat {
	r, ok := new(big.Rat).SetString(s)
	if !ok {
		t.Fatalf("bad rational %q", s)
	}
	return r
}

// --- differential test against the reference implementation -----------------

func TestExactGaussianMatchesReference(t *testing.T) {
	f, err := os.Open("testdata/cks20_reference_vectors.txt")
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 1<<20), 1<<24)
	cases := 0
	for sc.Scan() {
		line := sc.Text()
		if strings.HasPrefix(line, "#") || line == "" {
			continue
		}
		p := strings.Split(line, "|")
		name, s2, seed, tStr, wStr, xs := p[0], p[1], p[2], p[3], p[4], strings.Split(p[5], ",")
		src := &shaWords{seed: []byte(seed)}
		g := newCKS20(mustRat(t, s2), src)
		if g.t.String() != tStr {
			t.Fatalf("%s: t=%s, reference %s", name, g.t, tStr)
		}
		for i, want := range xs {
			if got := g.dgauss().String(); got != want {
				t.Fatalf("%s: sample %d = %s, reference %s", name, i, got, want)
			}
		}
		if wStr != new(big.Int).SetUint64(src.words).String() {
			t.Fatalf("%s: consumed %d words, reference %s", name, src.words, wStr)
		}
		// optimized implementation (production path): same vectors, same consumption
		srcF := &shaWords{seed: []byte(seed)}
		gf := newCKS20Fast(mustRat(t, s2), srcF)
		if gf.t.String() != tStr {
			t.Fatalf("%s: fast t=%s, reference %s", name, gf.t, tStr)
		}
		for i, want := range xs {
			if got := gf.dgaussBig().String(); got != want {
				t.Fatalf("%s: fast sample %d = %s, reference %s", name, i, got, want)
			}
		}
		if wStr != new(big.Int).SetUint64(srcF.words).String() {
			t.Fatalf("%s: fast consumed %d words, reference %s", name, srcF.words, wStr)
		}
		t.Logf("%-13s sigma2=%-40s t=%s: %d samples identical, %d words identical (transcription and optimized)", name, s2, tStr, len(xs), src.words)
		cases++
	}
	if cases != 10 {
		t.Fatalf("read %d cases", cases)
	}
}

// --- component and goodness-of-fit regression checks (crypto/rand) -------------

func TestExactGaussianComponents(t *testing.T) {
	g := newCKS20(big.NewRat(1, 1), newCryptoWords())
	const n = 400000
	for _, x := range []string{"0", "1/3", "1", "5/2", "7"} {
		r := mustRat(t, x)
		c := 0
		for i := 0; i < n; i++ {
			if g.bernoulliExp(r) {
				c++
			}
		}
		xf, _ := r.Float64()
		p := math.Exp(-xf)
		z := (float64(c) - n*p) / math.Sqrt(n*p*(1-p)+1e-300)
		t.Logf("Bernoulli(exp(-%s)): freq %.5f, exact %.5f, z=%.2f", x, float64(c)/n, p, z)
		if math.Abs(z) > 5 || (p == 1 && c != n) {
			t.Errorf("Bernoulli(exp(-%s)) off: z=%.2f", x, z)
		}
	}
	// discrete Laplace with t = 4: Pr[x] = exp(-|x|/t) (e^{1/t}-1)/(e^{1/t}+1)
	gl := newCKS20(big.NewRat(256, 25), newCryptoWords()) // t = floor(3.2)+1 = 4
	if gl.t.Int64() != 4 {
		t.Fatalf("t=%v", gl.t)
	}
	cnt := map[int64]int{}
	for i := 0; i < n; i++ {
		cnt[gl.dlaplace().Int64()]++
	}
	a := 1.0 / 4
	pmf := func(x int64) float64 {
		return math.Exp(-math.Abs(float64(x))*a) * (math.Exp(a) - 1) / (math.Exp(a) + 1)
	}
	chi, df := chi2Int(cnt, n, pmf, 40)
	t.Logf("discrete Laplace(t=4): chi2=%.1f df=%d", chi, df)
	if chi > float64(df)+6*math.Sqrt(2*float64(df)) {
		t.Errorf("discrete Laplace chi2 %.1f df %d", chi, df)
	}
}

// chi2Int compares integer counts with pmf on [-lim, lim] (tails pooled).
func chi2Int(cnt map[int64]int, n int, pmf func(int64) float64, lim int64) (float64, int) {
	chi, df := 0.0, -1
	tailObs, tailExp := 0.0, 1.0
	for x := -lim; x <= lim; x++ {
		e := float64(n) * pmf(x)
		tailExp -= pmf(x)
		if e < 5 {
			tailObs += float64(cnt[x])
			tailExp += pmf(x)
			continue
		}
		o := float64(cnt[x])
		chi += (o - e) * (o - e) / e
		df++
	}
	for x, c := range cnt {
		if x < -lim || x > lim {
			tailObs += float64(c)
		}
	}
	if e := tailExp * float64(n); e >= 5 {
		chi += (tailObs - e) * (tailObs - e) / e
		df++
	}
	return chi, df
}

func dgaussPMF(sigma2 float64) func(int64) float64 {
	z := 0.0
	lim := int64(40*math.Sqrt(sigma2)) + 40
	for x := -lim; x <= lim; x++ {
		z += math.Exp(-float64(x*x) / (2 * sigma2))
	}
	return func(x int64) float64 { return math.Exp(-float64(x*x)/(2*sigma2)) / z }
}

func TestExactGaussianPMFSmallSigma(t *testing.T) {
	const n = 400000
	for _, s2 := range []string{"1", "256/25", "7/3", "1024"} {
		r := mustRat(t, s2)
		g := newCKS20Fast(r, newCryptoWords())
		cnt := map[int64]int{}
		for i := 0; i < n; i++ {
			cnt[g.dgaussBig().Int64()]++
		}
		f, _ := r.Float64()
		chi, df := chi2Int(cnt, n, dgaussPMF(f), int64(10*math.Sqrt(f))+10)
		t.Logf("D_Z(sigma2=%s): chi2=%.1f df=%d", s2, chi, df)
		if chi > float64(df)+6*math.Sqrt(2*float64(df)) {
			t.Errorf("sigma2=%s: chi2 %.1f df %d", s2, chi, df)
		}
	}
}

// --- large sigma, RNS representation, independence -----------------------------

// D60 parameter literals: exact primes of LR-D60 and MNIST-N15-D60
// (R1-3_parameter_audit.md section 1.1; test-only profiles).
var (
	floodTestLRD60 = rlwe.ParametersLiteral{
		LogN: 15,
		Q: []uint64{0x1fffffffffc80001, 0xffffffffffc0001, 0x10000000001d0001, 0x10000000006e0001,
			0xfffffffff840001, 0x1000000000860001, 0x1000000000870001, 0x1000000000930001, 0xfffffffff6a0001},
		P:     []uint64{0x1fffffffffe10001, 0x1fffffffffe00001, 0x1fffffffffdd0001},
		Sigma: rlwe.DefaultSigma,
	}
	floodTestMNISTD60 = rlwe.ParametersLiteral{
		LogN: 15,
		Q: []uint64{0x1fffffffffdd0001, 0xffffffffffc0001, 0x10000000001d0001, 0x10000000006e0001,
			0xfffffffff840001, 0x1000000000860001, 0x1000000000870001},
		P:     []uint64{0x1fffffffffe10001, 0x1fffffffffe00001},
		Sigma: rlwe.DefaultSigma,
	}
)

func TestExactGaussianRNSRepresentation(t *testing.T) {
	for _, pc := range []struct {
		name string
		lit  rlwe.ParametersLiteral
		ls   uint
	}{{"LR-D60", floodTestLRD60, 45}, {"MNIST-N15-D60", floodTestMNISTD60, 49}, {"MNIST-runner", floodTestMNIST, 49}, {"LR-D60", floodTestLRD60, 65}} {
		params := floodParams(t, pc.lit)
		ringQ := params.RingQ()
		cfg := ExactDiscreteGaussianFloodingConfigPow2(pc.ls)
		s2, _ := cfg.parseSigma2()
		for _, level := range []int{0, 1, params.MaxLevel()} {
			seed := []byte(pc.name + string(rune('a'+level)))
			ref := newCKS20(s2, &shaWords{seed: seed})
			want := make([]*big.Int, ringQ.N)
			for j := range want {
				want[j] = ref.dgauss()
			}
			pol := ringQ.NewPolyLvl(level)
			newExactDiscreteGaussian(s2, ringQ, 1, func() wordSource { return &shaWords{seed: seed} }).readLvl(level, pol)
			// 3 workers: worker k fills [kN/3, (k+1)N/3) from its own stream seed||k
			polW := ringQ.NewPolyLvl(level)
			kk := 0
			newExactDiscreteGaussian(s2, ringQ, 3, func() wordSource { kk++; return &shaWords{seed: append(append([]byte{}, seed...), byte(kk))} }).readLvl(level, polW)
			wantW := make([]*big.Int, ringQ.N)
			for k := 0; k < 3; k++ {
				r := newCKS20(s2, &shaWords{seed: append(append([]byte{}, seed...), byte(k+1))})
				for j := k * ringQ.N / 3; j < (k+1)*ringQ.N/3; j++ {
					wantW[j] = r.dgauss()
				}
			}
			Q := big.NewInt(1)
			for i := 0; i <= level; i++ {
				Q.Mul(Q, new(big.Int).SetUint64(ringQ.Modulus[i]))
			}
			bad, wide := 0, 0
			for j := 0; j < ringQ.N; j++ {
				for i := 0; i <= level; i++ {
					if pol.Coeffs[i][j] >= ringQ.Modulus[i] {
						t.Fatalf("residue not reduced")
					}
				}
				if !want[j].IsInt64() {
					wide++
				}
				// exact residues: CRT(pol) == want mod Q_level
				if new(big.Int).Mod(new(big.Int).Sub(centeredCRT(ringQ, level, pol, j), want[j]), Q).Sign() != 0 {
					bad++
				}
				if new(big.Int).Mod(new(big.Int).Sub(centeredCRT(ringQ, level, polW, j), wantW[j]), Q).Sign() != 0 {
					bad++
				}
			}
			t.Logf("%s sigma=2^%d level=%d: %d coefficients, %d RNS mismatches, %d outside int64 (big path)", pc.name, pc.ls, level, ringQ.N, bad, wide)
			if bad != 0 {
				t.Fatalf("RNS representation wrong for %d coefficients", bad)
			}
		}
	}
	// forced big values through setSignedBig
	params := floodParams(t, floodTestLRD60)
	ringQ := params.RingQ()
	L := params.MaxLevel()
	pol := ringQ.NewPolyLvl(L)
	vals := []*big.Int{big.NewInt(0), big.NewInt(1), big.NewInt(-1), big.NewInt(math.MaxInt64), big.NewInt(math.MinInt64),
		new(big.Int).Lsh(big.NewInt(1), 63), new(big.Int).Neg(new(big.Int).Add(new(big.Int).Lsh(big.NewInt(1), 63), big.NewInt(5))),
		new(big.Int).Add(new(big.Int).Lsh(big.NewInt(1), 200), big.NewInt(7)), new(big.Int).Neg(new(big.Int).Lsh(big.NewInt(3), 300))}
	for k, v := range vals {
		setSignedBig(ringQ, L, pol, k, v)
		if got := centeredCRT(ringQ, L, pol, k); got.Cmp(v) != 0 {
			t.Fatalf("setSignedBig(%v) reconstructs %v", v, got)
		}
	}
}

func bigMoments(xs []*big.Int, sigma float64) (mean, varRatio, p1, p3, chiLow float64) {
	n := float64(len(xs))
	var s, s2 float64
	low := make([]float64, 256)
	for _, x := range xs {
		f, _ := new(big.Float).SetInt(x).Float64()
		f /= sigma
		s += f
		s2 += f * f
		if math.Abs(f) > 1 {
			p1++
		}
		if math.Abs(f) > 3 {
			p3++
		}
		low[new(big.Int).And(x, big.NewInt(255)).Int64()]++
	}
	e := n / 256
	for _, o := range low {
		chiLow += (o - e) * (o - e) / e
	}
	return s / n, s2 / n, p1 / n, p3 / n, chiLow
}

func TestExactGaussianLargeSigma(t *testing.T) {
	const n = 1 << 16
	for _, ls := range []uint{45, 46, 49, 50, 65} {
		cfg := ExactDiscreteGaussianFloodingConfigPow2(ls)
		s2, _ := cfg.parseSigma2()
		g := newCKS20Fast(s2, newCryptoWords())
		xs := make([]*big.Int, n)
		for i := range xs {
			xs[i] = g.dgaussBig()
		}
		mean, vr, p1, p3, chiLow := bigMoments(xs, math.Exp2(float64(ls)))
		// ideal: mean 0 (sd 1/sqrt n), var ratio 1 (sd sqrt(2/n)), P(|x|>s)=0.31731, P(|x|>3s)=0.0026998
		zs := []float64{mean * math.Sqrt(n), (vr - 1) / math.Sqrt(2.0/n),
			(p1 - 0.317311) / math.Sqrt(0.317311*(1-0.317311)/n), (p3 - 0.0026998) / math.Sqrt(0.0026998*(1-0.0026998)/n)}
		t.Logf("sigma=2^%d: mean/sigma=%.4f var/sigma^2=%.4f P(|x|>s)=%.4f P(|x|>3s)=%.5f lowbyte chi2=%.0f (df 255); z=%.2f %.2f %.2f %.2f; laplace/sample=%.3f uniform/sample=%.2f",
			ls, mean, vr, p1, p3, chiLow, zs[0], zs[1], zs[2], zs[3], float64(g.nLaplace)/n, float64(g.nUniform)/n)
		for _, z := range zs {
			if math.Abs(z) > 5 {
				t.Errorf("sigma=2^%d: z=%.2f", ls, z)
			}
		}
		if chiLow > 255+6*math.Sqrt(510) {
			t.Errorf("sigma=2^%d: low-byte chi2 %.0f", ls, chiLow)
		}
	}
}

func corr(a, b []float64) float64 {
	var sa, sb, saa, sbb, sab float64
	for i := range a {
		sa, sb = sa+a[i], sb+b[i]
		saa, sbb, sab = saa+a[i]*a[i], sbb+b[i]*b[i], sab+a[i]*b[i]
	}
	n := float64(len(a))
	return (sab/n - sa/n*sb/n) / math.Sqrt((saa/n-sa*sa/n/n)*(sbb/n-sb*sb/n/n))
}

func polyFloats(ringQ *ring.Ring, pol *ring.Poly, sigma float64) []float64 {
	out := make([]float64, ringQ.N)
	for j := range out {
		f, _ := new(big.Float).SetInt(centeredCRT(ringQ, 0, pol, j)).Float64()
		out[j] = f / sigma
	}
	return out
}

func TestExactGaussianIndependence(t *testing.T) {
	params := floodParams(t, floodTestMNISTD60)
	ringQ := params.RingQ()
	cfg := ExactDiscreteGaussianFloodingConfigPow2(49)
	// level 0 only: q_0 ~ 2^61 >> 2^49, so centered residues mod q_0 are the samples
	s1, err := newFloodingSampler(params, cfg)
	if err != nil {
		t.Fatal(err)
	}
	s2, err := newFloodingSampler(params, cfg)
	if err != nil {
		t.Fatal(err)
	}
	sig := math.Exp2(49)
	p1, p2, p3 := ringQ.NewPolyLvl(0), ringQ.NewPolyLvl(0), ringQ.NewPolyLvl(0)
	s1.readLvl(0, p1)
	s1.readLvl(0, p2) // next polynomial, same sampler
	s2.readLvl(0, p3) // independent sampler
	a, b, c := polyFloats(ringQ, p1, sig), polyFloats(ringQ, p2, sig), polyFloats(ringQ, p3, sig)
	lim := 5 / math.Sqrt(float64(ringQ.N))
	lag := func(v []float64, k int) float64 { return corr(v[:len(v)-k], v[k:]) }
	sq := func(v []float64) []float64 {
		o := make([]float64, len(v))
		for i, x := range v {
			o[i] = x * x
		}
		return o
	}
	checks := map[string]float64{
		"lag1(poly)": lag(a, 1), "lag2(poly)": lag(a, 2), "lag1(x^2)": lag(sq(a), 1),
		"poly vs next poly (same sampler)": corr(a, b), "poly vs other sampler": corr(a, c), "x^2 vs other sampler": corr(sq(a), sq(c)),
	}
	for k, v := range checks {
		t.Logf("%-34s rho=%+.4f (|rho| limit %.4f)", k, v, lim)
		if math.Abs(v) > lim {
			t.Errorf("%s: correlation %.4f", k, v)
		}
	}
	eq := 0
	for j := range a {
		if p1.Coeffs[0][j] == p3.Coeffs[0][j] {
			eq++
		}
	}
	if eq > 2 {
		t.Errorf("%d equal coefficients between independent samplers", eq)
	}
}

// --- configuration ---------------------------------------------------------------

func TestExactGaussianConfig(t *testing.T) {
	params := floodParams(t, floodTestLRD60)
	good := ExactDiscreteGaussianFloodingConfigPow2(45)
	if err := good.Validate(params); err != nil {
		t.Fatal(err)
	}
	if good.Sigma2 != new(big.Int).Lsh(big.NewInt(1), 90).String() || good.Sigma != math.Exp2(45) || good.Bound != 0 {
		t.Fatalf("config %+v", good)
	}
	t.Logf("config: %v", good)
	if _, err := good.CheckHeadroom(params, 1, 2, 40); err == nil {
		t.Error("CheckHeadroom must refuse an untruncated distribution")
	}
	bad := []FloodingConfig{
		{Distribution: FloodingDiscreteGaussianExact},
		{Distribution: FloodingDiscreteGaussianExact, Sigma2: "-4"},
		{Distribution: FloodingDiscreteGaussianExact, Sigma2: "0"},
		{Distribution: FloodingDiscreteGaussianExact, Sigma2: "abc"},
		{Distribution: FloodingDiscreteGaussianExact, Sigma2: "1237940039285380274899124224", Bound: 6 << 45},       // explicit tail cut refused
		{Distribution: FloodingDiscreteGaussianExact, Sigma2: "1237940039285380274899124224", Sigma: math.Exp2(40)}, // inconsistent sigma
		{Distribution: FloodingDiscreteGaussianExact, Sigma2: new(big.Int).Lsh(big.NewInt(1), 300).String()},
	}
	for _, c := range bad {
		if err := c.Validate(params); err == nil {
			t.Errorf("accepted %+v", c)
		}
	}
	// non-power-of-two rational sigma^2 is accepted
	if err := ExactDiscreteGaussianFloodingConfig(big.NewRat(1e15+7, 3)).Validate(params); err != nil {
		t.Error(err)
	}
}

// GenShare with the exact sampler: phi = d - c*s is the sampled integer
// polynomial (fresh per call) with the expected spread.
func TestGenShareExactGaussian(t *testing.T) {
	params := floodParams(t, floodTestMNISTD60)
	cfg := ExactDiscreteGaussianFloodingConfigPow2(49)
	dec, err := NewDecryptorWithFlooding(params, cfg)
	if err != nil {
		t.Fatal(err)
	}
	kgen := NewKeyGenerator(params)
	sk, _ := kgen.GenKeyPair("owner0")
	ids := NewIDSet()
	ids.Add("owner0")
	level := 1
	ct := NewCiphertext(params, ids, level)
	prng, err := utils.NewPRNG()
	if err != nil {
		t.Fatal(err)
	}
	ring.NewUniformSampler(prng, params.RingQ()).ReadLvl(level, ct.Value["owner0"])
	ringQ := params.RingQ()
	prod := expectedProduct(params, ct, sk)
	var phis [2][]float64
	for k := 0; k < 2; k++ {
		d := dec.GenShare(ct, sk)
		diff := ringQ.NewPolyLvl(level)
		ringQ.SubLvl(level, d, prod, diff)
		phis[k] = make([]float64, ringQ.N)
		ss := 0.0
		for j := 0; j < ringQ.N; j++ {
			f, _ := new(big.Float).SetInt(centeredCRT(ringQ, level, diff, j)).Float64()
			phis[k][j] = f / math.Exp2(49)
			ss += phis[k][j] * phis[k][j]
		}
		vr := ss / float64(ringQ.N)
		t.Logf("GenShare %d: var(phi)/sigma^2 = %.4f", k, vr)
		if math.Abs(vr-1) > 5*math.Sqrt(2/float64(ringQ.N)) {
			t.Errorf("phi variance ratio %.4f", vr)
		}
	}
	if r := corr(phis[0], phis[1]); math.Abs(r) > 5/math.Sqrt(float64(ringQ.N)) {
		t.Errorf("two GenShare calls correlated: %.4f", r)
	}
}

// --- cost (EXACT_BENCH=1) ----------------------------------------------------------

func TestExactGaussianCost(t *testing.T) {
	if os.Getenv("EXACT_BENCH") != "1" {
		t.Skip("set EXACT_BENCH=1")
	}
	t.Logf("CSV,profile,logN,level,flooding,impl,init_us,poly_ms_mean,poly_ms_min,poly_ms_max,polys,ns_per_coeff,alloc_MiB_per_poly,mallocs_per_coeff,laplace_per_sample,uniform_per_sample,heap_inuse_MiB")
	type pc struct {
		name  string
		lit   rlwe.ParametersLiteral
		level int
		cfgs  []FloodingConfig
	}
	plans := []pc{
		{"MNIST-runner(N=2^14)", floodTestMNIST, 1, []FloodingConfig{LegacyFloodingConfig(), WideGaussianFloodingConfig(45, 6),
			ExactDiscreteGaussianFloodingConfigPow2(45), ExactDiscreteGaussianFloodingConfigPow2(49)}},
		{"LR-D60(N=2^15)", floodTestLRD60, 1, []FloodingConfig{LegacyFloodingConfig(), WideGaussianFloodingConfig(45, 6),
			ExactDiscreteGaussianFloodingConfigPow2(45), ExactDiscreteGaussianFloodingConfigPow2(46)}},
		{"LR-D60(N=2^15)", floodTestLRD60, 2, []FloodingConfig{ExactDiscreteGaussianFloodingConfigPow2(45)}},
		{"MNIST-N15-D60(N=2^15)", floodTestMNISTD60, 1, []FloodingConfig{LegacyFloodingConfig(), WideGaussianFloodingConfig(49, 6),
			ExactDiscreteGaussianFloodingConfigPow2(49), ExactDiscreteGaussianFloodingConfigPow2(50)}},
	}
	for _, p := range plans {
		params := floodParams(t, p.lit)
		ringQ := params.RingQ()
		for _, cfg := range p.cfgs {
			for _, impl := range costImpls(cfg) {
				const inits = 50
				t0 := time.Now()
				var s floodingSampler
				for i := 0; i < inits; i++ {
					var err error
					if s, err = newFloodingSampler(params, cfg); err != nil {
						t.Fatal(err)
					}
					s = impl.wrap(s, cfg, ringQ)
				}
				initUs := float64(time.Since(t0).Microseconds()) / inits
				pol := ringQ.NewPolyLvl(p.level)
				s.readLvl(p.level, pol) // warm-up (first crypto/rand fill)
				polys := 10
				var ms0, ms1 runtime.MemStats
				runtime.GC()
				runtime.ReadMemStats(&ms0)
				var tot, mn, mx float64
				mn = math.Inf(1)
				var l0, u0 uint64
				if e, ok := s.(laplaceCounter); ok {
					l0, u0 = e.counters()
				}
				for k := 0; k < polys; k++ {
					t1 := time.Now()
					s.readLvl(p.level, pol)
					d := float64(time.Since(t1).Microseconds()) / 1000
					tot += d
					mn, mx = math.Min(mn, d), math.Max(mx, d)
				}
				runtime.ReadMemStats(&ms1)
				nc := float64(polys * ringQ.N)
				lap, uni := math.NaN(), math.NaN()
				if e, ok := s.(laplaceCounter); ok {
					l1, u1 := e.counters()
					lap, uni = float64(l1-l0)/nc, float64(u1-u0)/nc
				}
				t.Logf("CSV,%s,%d,%d,%s,%s,%.1f,%.2f,%.2f,%.2f,%d,%.0f,%.2f,%.1f,%.3f,%.2f,%.1f", p.name, params.LogN(), p.level,
					strings.ReplaceAll(cfg.String(), ", ", ";"), impl.name, initUs, tot/float64(polys), mn, mx, polys, tot*1e6/nc,
					float64(ms1.TotalAlloc-ms0.TotalAlloc)/float64(polys)/(1<<20), float64(ms1.Mallocs-ms0.Mallocs)/nc, lap, uni,
					float64(ms1.HeapInuse)/(1<<20))
			}
		}
	}
}

type laplaceCounter interface{ counters() (uint64, uint64) }

// refExact is the pre-optimization adapter (transcription cks20, one goroutine),
// kept for before/after measurements.
type refExact struct {
	g     *cks20
	ringQ *ring.Ring
}

func (s *refExact) readLvl(level int, pol *ring.Poly) {
	for j := 0; j < s.ringQ.N; j++ {
		setSignedBig(s.ringQ, level, pol, j, s.g.dgauss())
	}
}
func (s *refExact) counters() (uint64, uint64) { return s.g.nLaplace, s.g.nUniform }

type costImpl struct {
	name string
	wrap func(floodingSampler, FloodingConfig, *ring.Ring) floodingSampler
}

func costImpls(cfg FloodingConfig) []costImpl {
	keep := costImpl{"default", func(s floodingSampler, _ FloodingConfig, _ *ring.Ring) floodingSampler { return s }}
	if cfg.Distribution != FloodingDiscreteGaussianExact {
		return []costImpl{keep}
	}
	s2, _ := cfg.parseSigma2()
	mk := func(w int) func(floodingSampler, FloodingConfig, *ring.Ring) floodingSampler {
		return func(_ floodingSampler, _ FloodingConfig, r *ring.Ring) floodingSampler {
			return newExactDiscreteGaussian(s2, r, w, func() wordSource { return newCryptoWords() })
		}
	}
	return []costImpl{
		{"before(transcription;1 thread)", func(_ floodingSampler, _ FloodingConfig, r *ring.Ring) floodingSampler {
			return &refExact{g: newCKS20(s2, newCryptoWords()), ringQ: r}
		}},
		{"optimized(1 thread)", mk(1)},
		{"optimized(2 workers)", mk(2)},
		{"optimized(4 workers)", mk(4)},
	}
}

// --- optimized vs transcription: identical outputs and consumption -------------

// TestExactGaussianFastEquivalence drives cks20 (line-by-line transcription of
// discretegauss.py) and cks20Fast (production) with the same deterministic word
// stream on sigma^2 values that exercise every code path: power-of-two and
// non-power-of-two 2*sigma^2 numerators, non-integer sigma^2, sd > 1, t < 2^64
// and t >= 2^64, uint64->big overflow in the Laplace magnitude and in
// Bernoulli denominators. Equality of every sample and of the number of words
// consumed shows the two compute the same function of the random stream.
func TestExactGaussianFastEquivalence(t *testing.T) {
	cases := []struct {
		s2 string
		n  int
	}{
		{"1", 20000}, {"1/2", 20000}, {"256/25", 20000}, {"7/3", 20000}, {"1000003/17", 20000}, {"6", 20000},
		{"1237940039285380274899124224", 20000},            // 2^90 (LR-D60, sigma = 2^45)
		{"4951760157141521099596496896", 20000},            // 2^92
		{"316912650057057350374175801344", 20000},          // 2^98 (MNIST-D60, sigma = 2^49)
		{"1267650600228229401496703205376", 20000},         // 2^100
		{"3*(2^45)^2+11", 0},                               // placeholder replaced below
		{"85070591730234615865843651857942052864/3", 5000}, // 2^126/3
		{"1361129467683753853853498429727072845824", 5000}, // 2^130: t >= 2^64
		{"1361129467683753853853498429727072845825/7", 5000},
		{"85070591730234615847396907784232501249", 5000}, // (2^63-1)^2-ish range: Laplace overflow 2^63
	}
	cases[10].s2 = new(big.Int).Add(new(big.Int).Mul(big.NewInt(3), new(big.Int).Lsh(big.NewInt(1), 90)), big.NewInt(11)).String() + "/5"
	cases[10].n = 20000
	for ci, c := range cases {
		s2 := mustRat(t, c.s2)
		seed := []byte(fmt.Sprintf("equiv-%d", ci))
		ra, rb := &shaWords{seed: seed}, &shaWords{seed: seed}
		a, b := newCKS20(s2, ra), newCKS20Fast(s2, rb)
		bigCnt := 0
		for i := 0; i < c.n; i++ {
			x, y := a.dgauss(), b.dgaussBig()
			if x.Cmp(y) != 0 {
				t.Fatalf("sigma2=%s sample %d: transcription %v, optimized %v", c.s2, i, x, y)
			}
			if ra.words != rb.words {
				t.Fatalf("sigma2=%s sample %d: words %d vs %d", c.s2, i, ra.words, rb.words)
			}
			if !x.IsInt64() {
				bigCnt++
			}
		}
		if a.nUniform != b.nUniform || a.nLaplace != b.nLaplace {
			t.Fatalf("sigma2=%s: counters differ", c.s2)
		}
		t.Logf("sigma2=%-45s t=%s: %d samples, %d words identical (%d outside int64)", c.s2, b.t, c.n, ra.words, bigCnt)
	}
}

// Allocation check on the production path: amortised allocations per
// coefficient (only values outside int64 allocate).
func TestExactGaussianFastAllocs(t *testing.T) {
	for _, ls := range []uint{45, 49} {
		cfg := ExactDiscreteGaussianFloodingConfigPow2(ls)
		s2, _ := cfg.parseSigma2()
		g := newCKS20Fast(s2, newCryptoWords())
		for i := 0; i < 1000; i++ {
			g.dgauss()
		}
		a := testing.AllocsPerRun(20000, func() { g.dgauss() })
		t.Logf("sigma=2^%d: %.4f allocations per sample", ls, a)
		if a > 0.01 {
			t.Errorf("sigma=2^%d: %.4f allocations per sample", ls, a)
		}
	}
}
